package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct { // 01 EMP-REC, 17 bytes
	ErId    string          // PIC X(5) @0 len=5
	ErDept  string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate  decimal.Decimal // PIC 9(3)V99 @12 len=5
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsFirstFlag string = "Y" // PIC X len=1 = "Y"
var WsPrevDept string = "   " // PIC X(3) len=3 = SPACES
var WsRegHours decimal.Decimal = decimal.NewFromInt(0) // PIC 9(3)V9 len=4 = 0
var WsOtHours decimal.Decimal = decimal.NewFromInt(0) // PIC 9(3)V9 len=4 = 0
var WsGross decimal.Decimal = decimal.NewFromInt(0) // PIC 9(7)V99 len=9 = 0
var WsDeptTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsDeptCount int64 = 0 // PIC 9(3) len=3 = 0
var WsGrandTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(11)V99 len=13 = 0
var WsGrandCount int64 = 0 // PIC 9(5) len=5 = 0
var WsHoursEd string // PIC ZZ9.9 len=5
var WsRateEd string // PIC ZZ9.99 len=6
var WsGrossEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsDeptEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsGrandEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var empRec EmpRec
var empFile *os.File
var empScanner *bufio.Scanner

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func storeDec(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := v.Truncate(scale)
	modulus := decimal.New(1, int32(intDigits)+scale)
	scaled := t.Shift(scale)
	r := scaled.Mod(modulus)
	return r.Shift(-scale)
}

func storeInt(v int64, digits int) int64 {
	m := int64(1)
	for i := 0; i < digits; i++ {
		m *= 10
	}
	if m == 0 {
		return v
	}
	return v % m
}

func formatEdited(v decimal.Decimal, intPat string, fracScale int) string {
	t := v.Truncate(int32(fracScale))
	abs := t.Abs()
	scaled := abs.Shift(int32(fracScale))
	scaledInt := scaled.IntPart()
	var powFrac int64 = 1
	for i := 0; i < fracScale; i++ {
		powFrac *= 10
	}
	slots := 0
	for _, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			slots++
		}
	}
	var powSlots int64 = 1
	for i := 0; i < slots; i++ {
		powSlots *= 10
	}
	var intPart, fracPart int64
	if fracScale > 0 {
		intPart = (scaledInt / powFrac) % powSlots
		fracPart = scaledInt % powFrac
		if fracPart < 0 {
			fracPart = -fracPart
		}
		if intPart < 0 {
			intPart = -intPart
		}
	} else {
		intPart = scaledInt % powSlots
		if intPart < 0 {
			intPart = -intPart
		}
		fracPart = 0
	}
	digits := fmt.Sprintf("%0*d", slots, intPart)
	firstNZ := slots - 1
	for i := 0; i < slots; i++ {
		if digits[i] != '0' {
			firstNZ = i
			break
		}
	}
	var sb strings.Builder
	slotIdx := 0
	for _, ch := range intPat {
		if ch == ',' {
			leftIdx := slotIdx - 1
			if firstNZ > leftIdx {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		} else {
			d := digits[slotIdx]
			if ch == 'Z' && slotIdx < firstNZ {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(d)
			}
			slotIdx++
		}
	}
	if fracScale > 0 {
		sb.WriteByte('.')
		fracStr := fmt.Sprintf("%0*d", fracScale, fracPart)
		sb.WriteString(fracStr)
	}
	return sb.String()
}

func parseHours(s string) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	return decimal.New(n, -1)
}

func parseRate(s string) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	return decimal.New(n, -2)
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	empFile = f
	empScanner = bufio.NewScanner(f)
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		DeptBreakPara()
	}
	f.Close()
	GrandPara()
}

func ReadPara() {
	if empScanner.Scan() {
		line := empScanner.Text()
		if len(line) < 17 {
			line += strings.Repeat(" ", 17-len(line))
		} else if len(line) > 17 {
			line = line[:17]
		}
		empRec.ErId = line[0:5]
		empRec.ErDept = line[5:8]
		hStr := line[8:12]
		rStr := line[12:17]
		empRec.ErHours = parseHours(hStr)
		empRec.ErRate = parseRate(rStr)
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevDept = empRec.ErDept
		WsFirstFlag = "N"
	} else {
		if empRec.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = empRec.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	forty := decimal.NewFromInt(40)
	if empRec.ErHours.GreaterThan(forty) {
		WsRegHours = storeDec(forty, 3, 1)
		diff := empRec.ErHours.Sub(forty)
		WsOtHours = storeDec(diff, 3, 1)
	} else {
		WsRegHours = storeDec(empRec.ErHours, 3, 1)
		WsOtHours = storeDec(decimal.NewFromInt(0), 3, 1)
	}
	onePointFive := decimal.New(15, -1)
	term1 := WsRegHours.Mul(empRec.ErRate)
	term2 := WsOtHours.Mul(empRec.ErRate).Mul(onePointFive)
	sum := term1.Add(term2)
	rounded := sum.Round(2)
	WsGross = storeDec(rounded, 7, 2)
	WsDeptTotal = storeDec(WsDeptTotal.Add(WsGross), 9, 2)
	WsDeptCount = storeInt(WsDeptCount+1, 3)
	WsGrandTotal = storeDec(WsGrandTotal.Add(WsGross), 11, 2)
	WsGrandCount = storeInt(WsGrandCount+1, 5)
	WsHoursEd = formatEdited(empRec.ErHours, "ZZ9", 1)
	WsRateEd = formatEdited(empRec.ErRate, "ZZ9", 2)
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9", 2)
	var sb strings.Builder
	sb.WriteString(empRec.ErId)
	sb.WriteString(" ")
	sb.WriteString(empRec.ErDept)
	sb.WriteString(" ")
	sb.WriteString(WsHoursEd)
	sb.WriteString(" ")
	sb.WriteString(WsRateEd)
	sb.WriteString(" ")
	sb.WriteString(WsGrossEd)
	sb.WriteString("\n")
	os.Stdout.WriteString(sb.String())
}

func DeptBreakPara() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9", 2)
	var sb strings.Builder
	sb.WriteString("  DEPT ")
	sb.WriteString(WsPrevDept)
	sb.WriteString(" EMPLOYEES: ")
	sb.WriteString(fmt.Sprintf("%03d", WsDeptCount))
	sb.WriteString(" TOTAL: ")
	sb.WriteString(WsDeptEd)
	sb.WriteString("\n")
	os.Stdout.WriteString(sb.String())
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GrandPara() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9", 2)
	var sb strings.Builder
	sb.WriteString("GRAND TOTAL (")
	sb.WriteString(fmt.Sprintf("%05d", WsGrandCount))
	sb.WriteString("): ")
	sb.WriteString(WsGrandEd)
	sb.WriteString("\n")
	os.Stdout.WriteString(sb.String())
}

func main() {
	MainPara()
}
